/**
 * The merged `unmodel/revana` catalog — every model Revana lists, across all
 * nine addresses.
 *
 * **Importable from `./index.ts` and nowhere else.** This module is the union
 * of every kind's slice, so anything that reaches it pulls in every kind's
 * rows. Each validator imports its own `gen/models-<address>.gen.ts` slice
 * directly, which is what keeps `unmodel/video` from shipping ninety-nine
 * language models.
 *
 * The rows are generated by `scripts/codegen-revana.ts` from Revana's own
 * keyless catalog (`GET https://api.revana.si/v1/models`, snapshotted at
 * `data/revana/models.json`) — kind 3 in `src/providers/HAND_CATALOGS.md`.
 * Revana is not in models.dev.
 *
 * Two things about every row, stated once:
 *
 * - **`cost` is the LISTED price where one flat rate exists**, and absent
 *   where the rate is keyed by setting (`"720p+audio"`) — those live in the
 *   price tables and are resolved per request by `revanaCostUSD`. Either way
 *   it is the first route's price; see `REVANA_PRICING_CAVEAT`.
 * - **No release dates.** Revana publishes none, and the upstream vendors'
 *   dates describe the weights rather than the day this router started serving
 *   them.
 */

import type { ModelInfo, ProviderInfo } from "../../core/catalog-types";
import { chatModels } from "./gen/models-chat.gen";
import { imageModels } from "./gen/models-image.gen";
import { musicModels } from "./gen/models-music.gen";
import { ttsModels } from "./gen/models-tts.gen";
import { videoModels } from "./gen/models-video.gen";
import { REVANA_BASE_URL } from "./urls";

/**
 * Who this is, and where the key comes from.
 *
 * `REVANA_API_KEY` is the name Revana's own samples read: "POST
 * https://api.revana.si/v1/generations with `Authorization: Bearer
 * $REVANA_API_KEY`" (https://revana.si/llms-full.txt, read 2026-11-12).
 */
export const provider = {
  id: "revana",
  name: "Revana",
  env: ["REVANA_API_KEY"],
  doc: "https://revana.si/docs",
  api: REVANA_BASE_URL,
} as const satisfies ProviderInfo;

/**
 * Every Revana model, keyed by id. The ids are disjoint by construction —
 * `scripts/codegen-revana.ts` fails on a duplicate, and each catalog row has
 * exactly one `kind`.
 */
export const models = {
  ...chatModels,
  ...imageModels,
  ...musicModels,
  ...ttsModels,
  ...videoModels,
} as const satisfies Record<string, ModelInfo>;

export type RevanaModelId = keyof typeof models;
